{
  "results": [
    {
      "paperId": "7709860051778179755",
      "primaryId": "arxiv:2409.06481",
      "ids": {
        "arxiv": [
          "2409.06481"
        ]
      },
      "title": "NeIn: Telling What You Don't Want",
      "abstract": "Negation is a fundamental linguistic concept used by humans to convey information that they do not desire. Despite this, minimal research has focused on negation within text-guided image editing. This lack of research means that vision-language models (VLMs) for image editing may struggle to understand negation, implying that they struggle to provide accurate results. One barrier to achieving human-level intelligence is the lack of a standard collection by which research into negation can be evaluated. This paper presents the first large-scale dataset, Negative Instruction (NeIn), for studying negation within instruction-based image editing. Our dataset comprises 366,957 quintuplets, i.e., source image, original caption, selected object, negative sentence, and target image in total, including 342,775 queries for training and 24,182 queries for benchmarking image editing methods. Specifically, we automatically generate NeIn based on a large, existing vision-language dataset, MS-COCO, via two steps: generation and filtering. During the generation phase, we leverage two VLMs, BLIP and InstructPix2Pix (fine-tuned on MagicBrush dataset), to generate NeIn's samples and the negative clauses that expresses the content of the source image. In the subsequent filtering phase, we apply BLIP and LLaVA-NeXT to remove erroneous samples. Additionally, we introduce an evaluation protocol to assess the negation understanding for image editing models. Extensive experiments using our dataset across multiple VLMs for text-guided image editing demonstrate that even recent state-of-the-art VLMs struggle to understand negative queries.",
      "score": 0.6485108747389209
    },
    {
      "paperId": "2976232887859463792",
      "primaryId": "arxiv:2411.00056",
      "ids": {
        "arxiv": [
          "2411.00056"
        ]
      },
      "title": "Generating Diverse Negations from Affirmative Sentences",
      "abstract": "Despite the impressive performance of large language models across various tasks, they often struggle with reasoning under negated statements. Negations are important in real-world applications as they encode negative polarity in verb phrases, clauses, or other expressions. Nevertheless, they are underrepresented in current benchmarks, which mainly include basic negation forms and overlook more complex ones, resulting in insufficient data for training a language model. In this work, we propose NegVerse, a method that tackles the lack of negation datasets by producing a diverse range of negation types from affirmative sentences, including verbal, non-verbal, and affixal forms commonly found in English text. We provide new rules for masking parts of sentences where negations are most likely to occur, based on syntactic structure and use a frozen baseline LLM and prompt tuning to generate negated sentences. We also propose a filtering mechanism to identify negation cues and remove degenerate examples, producing a diverse range of meaningful perturbations. Our results show that NegVerse outperforms existing methods and generates negations with higher lexical similarity to the original sentences, better syntactic preservation and negation diversity. The code is available in https://github.com/DarianRodriguez/NegVerse",
      "score": 0.6121241957708197
    },
    {
      "paperId": "3993946668021156579",
      "primaryId": "pmid:34363177",
      "ids": {
        "doi": [
          "10.1007/s10936-021-09792-1"
        ],
        "pmid": [
          "34363177"
        ]
      },
      "title": "Negative clauses imply affirmative topics and affirmative antecedents.",
      "abstract": "We propose that negative clauses are generally interpreted as if the affirmative portion of the clause is under discussion, a likely topic.",
      "score": 0.6031840971858174
    },
    {
      "paperId": "7320850968756381279",
      "primaryId": "arxiv:2406.07492",
      "ids": {
        "arxiv": [
          "2406.07492"
        ]
      },
      "title": "Paraphrasing in Affirmative Terms Improves Negation Understanding",
      "abstract": "Negation is a common linguistic phenomenon. Yet language models face challenges with negation in many natural language understanding tasks such as question answering and natural language inference. In this paper, we experiment with seamless strategies that incorporate affirmative interpretations (i.e., paraphrases without negation) to make models more robust against negation. Crucially, our affirmative interpretations are obtained automatically. We show improvements with CondaQA, a large corpus requiring reasoning with negation, and five natural language understanding tasks.",
      "score": 0.5552423109749091
    },
    {
      "paperId": "197289782643232583",
      "primaryId": "arxiv:2210.14486",
      "ids": {
        "arxiv": [
          "2210.14486"
        ]
      },
      "title": "Leveraging Affirmative Interpretations from Negation Improves Natural Language Understanding",
      "abstract": "Negation poses a challenge in many natural language understanding tasks. Inspired by the fact that understanding a negated statement often requires humans to infer affirmative interpretations, in this paper we show that doing so benefits models for three natural language understanding tasks. We present an automated procedure to collect pairs of sentences with negation and their affirmative interpretations, resulting in over 150,000 pairs. Experimental results show that leveraging these pairs helps (a) T5 generate affirmative interpretations from negations in a previous benchmark, and (b) a RoBERTa-based classifier solve the task of natural language inference. We also leverage our pairs to build a plug-and-play neural generator that given a negated statement generates an affirmative interpretation. Then, we incorporate the pretrained generator into a RoBERTa-based classifier for sentiment analysis and show that doing so improves the results. Crucially, our proposal does not require any manual effort.",
      "score": 0.5506073655352404
    }
  ]
}
```

